-- ════════════════════════════════════════════════════════════
-- HR — attendance, shifts, leave, holidays
-- Daily attendance, shift rosters, regularisation and WFH requests, leave requests / balances / policies and the holiday calendar.
-- Generated by scripts/db/generate.ts — edit config.ts / types.ts, then re-run.
-- ════════════════════════════════════════════════════════════

-- One row per user per day; check_in / check_out keep the exact string the app writes.
create table if not exists crm.attendance_records (
  id                  text not null,
  org_id              text not null,
  user_id             text,
  date                date,
  status              text, -- ON_LEAVE | WFH | PRESENT | ABSENT | LATE | HALF_DAY
  check_in            text,
  check_out           text,
  mode                text, -- OFFICE | WFH
  late_by_minutes     numeric,
  worked_on_off_day   boolean,
  _extra              jsonb not null default '{}'::jsonb, -- values that don't fit a typed column (kept losslessly)
  _position           double precision not null default 0, -- list order the app expects
  primary key (id)
);

-- Backs the "shifts" collection (type ShiftSchedule).
create table if not exists crm.shift_schedules (
  id               text not null,
  org_id           text not null,
  name             text,
  code             text,
  start_time       text,
  end_time         text,
  grace_minutes    numeric,
  working_hours    numeric,
  assigned_count   numeric,
  is_rotational    boolean,
  status           text, -- ACTIVE | INACTIVE
  _extra           jsonb not null default '{}'::jsonb, -- values that don't fit a typed column (kept losslessly)
  _position        double precision not null default 0, -- list order the app expects
  primary key (id)
);

-- Backs the "attendanceCorrections" collection (type AttendanceCorrectionRecord).
create table if not exists crm.attendance_corrections (
  id                    text not null,
