-- Backs the "leaveRequests" collection (type LeaveRequest).
create table if not exists crm.leave_requests (
  id                   text not null,
  org_id               text not null,
  user_id              text,
  leave_type           text, -- CASUAL | SICK | EARNED | UNPAID | COMP_OFF | MATERNITY | PATERNITY
  from_date            date,
  to_date              date,
  reason               text,
  status               text, -- APPROVED | CANCELLED | REJECTED | PENDING
  approver_id          text,
  decision_note        text,
  half_day             text, -- FIRST | SECOND
  days                 numeric,
  attachment_file_id   text,
  cancelled_at         timestamptz,
